#include "DeleteImageResultObject.h"

#include "graphqlservice/internal/Schema.h"

#include "graphqlservice/introspection/IntrospectionSchema.h"

#include <algorithm>
#include <functional>
#include <sstream>
#include <stdexcept>
#include <unordered_map>

using namespace std::literals;

namespace graphql::tagimg {
namespace object {

DeleteImageResult::DeleteImageResult(std::unique_ptr<const Concept> pimpl) noexcept
	: service::Object{ getTypeNames(), getResolvers() }
	, _pimpl { std::move(pimpl) }
{
}

service::TypeNames DeleteImageResult::getTypeNames() const noexcept
{
	return {
		R"gql(DeleteImageResult)gql"sv
	};
}

service::ResolverMap DeleteImageResult::getResolvers() const noexcept
{
	return {
		{ R"gql(deletedCount)gql"sv, [this](service::ResolverParams&& params) { return resolveDeletedCount(std::move(params)); } },
		{ R"gql(__typename)gql"sv, [this](service::ResolverParams&& params) { return resolve_typename(std::move(params)); } },
		{ R"gql(missingIds)gql"sv, [this](service::ResolverParams&& params) { return resolveMissingIds(std::move(params)); } }
	};
}

void DeleteImageResult::beginSelectionSet(const service::SelectionSetParams& params) const
{
	_pimpl->beginSelectionSet(params);
}

void DeleteImageResult::endSelectionSet(const service::SelectionSetParams& params) const
{
	_pimpl->endSelectionSet(params);
}

service::AwaitableResolver DeleteImageResult::resolveDeletedCount(service::ResolverParams&& params) const
{
	std::unique_lock resolverLock(_resolverMutex);
	service::SelectionSetParams selectionSetParams { static_cast<const service::SelectionSetParams&>(params) };
	auto directives = std::move(params.fieldDirectives);
	auto result = _pimpl->getDeletedCount(service::FieldParams { std::move(selectionSetParams), std::move(directives) });
	resolverLock.unlock();

	return service::ModifiedResult<int>::convert(std::move(result), std::move(params));
}

service::AwaitableResolver DeleteImageResult::resolveMissingIds(service::ResolverParams&& params) const
{
	std::unique_lock resolverLock(_resolverMutex);
	service::SelectionSetParams selectionSetParams { static_cast<const service::SelectionSetParams&>(params) };
	auto directives = std::move(params.fieldDirectives);
	auto result = _pimpl->getMissingIds(service::FieldParams { std::move(selectionSetParams), std::move(directives) });
	resolverLock.unlock();

	return service::ModifiedResult<response::IdType>::convert<service::TypeModifier::List>(std::move(result), std::move(params));
}

service::AwaitableResolver DeleteImageResult::resolve_typename(service::ResolverParams&& params) const
{
	return service::Result<std::string>::convert(std::string{ R"gql(DeleteImageResult)gql" }, std::move(params));
}

} // namespace object

void AddDeleteImageResultDetails(const std::shared_ptr<schema::ObjectType>& typeDeleteImageResult, const std::shared_ptr<schema::Schema>& schema)
{
	typeDeleteImageResult->AddFields({
		schema::Field::Make(R"gql(deletedCount)gql"sv, R"md(实际删除的图片数量。)md"sv, std::nullopt, schema->WrapType(introspection::TypeKind::NON_NULL, schema->LookupType(R"gql(Int)gql"sv))),
		schema::Field::Make(R"gql(missingIds)gql"sv, R"md(请求中不存在、因此未删除的图片 ID。)md"sv, std::nullopt, schema->WrapType(introspection::TypeKind::NON_NULL, schema->WrapType(introspection::TypeKind::LIST, schema->WrapType(introspection::TypeKind::NON_NULL, schema->LookupType(R"gql(ID)gql"sv)))))
	});
}

} // namespace graphql::tagimg
